scripts/main.gd:
extends Node

var scenario_id: String = ""

func _ready() -> void:
	_parse_user_args()
	if scenario_id.is_empty():
		call_deferred("_load_title")
	else:
		call_deferred("_load_scenario", scenario_id)

func _parse_user_args() -> void:
	var args := OS.get_cmdline_user_args()
	var out_path := ""
	var frames := 0
	var i := 0
	while i < args.size():
		match args[i]:
			"--scenario":
				if i + 1 < args.size():
					scenario_id = args[i+1]
					i += 1
			"--out":
				if i + 1 < args.size():
					out_path = args[i+1]
					i += 1
			"--frames":
				if i + 1 < args.size():
					frames = int(args[i+1])
					i += 1
		i += 1
	if not out_path.is_empty() and frames > 0:
		call_deferred("_setup_screenshot", out_path, frames)

func _setup_screenshot(path: String, frame_count: int) -> void:
	var timer := Timer.new()
	timer.one_shot = true
	timer.wait_time = float(frame_count) / 30.0
	timer.timeout.connect(_on_screenshot_timeout.bind(path))
	add_child(timer)
	timer.start()

func _on_screenshot_timeout(path: String) -> void:
	var img: Image = get_viewport().get_texture().get_image()
	img.save_png(path)
	get_tree().quit()

func _load_title() -> void:
	get_tree().change_scene_to_file("res://scenes/TitleScreen.tscn")

func _load_scenario(id: String) -> void:
	seed(abs(id.hash()) % 1000000)
	var err := get_tree().change_scene_to_file("res://scenes/Gameplay.tscn")
	if err != OK:
		push_error("Failed to load Gameplay scene")
		return
	await get_tree().physics_frame
	var gameplay: Node = get_tree().current_scene
	if gameplay and gameplay.has_method("start_scenario"):
		gameplay.start_scenario(id)
